package de.mcstack.craftcore;
import org.junit.jupiter.api.Test;
import java.sql.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class ShopStoreTest {
  Connection setup(String name)throws Exception {Connection c=DriverManager.getConnection("jdbc:h2:mem:"+name+";MODE=MySQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=5000");try(Statement s=c.createStatement()){s.execute("CREATE TABLE pending_deliveries(id VARCHAR(36) PRIMARY KEY,player_uuid VARCHAR(36),item_nbt LONGTEXT,amount INT,source VARCHAR(32),status VARCHAR(16))");s.execute("CREATE TABLE accounts(uuid VARCHAR(36) PRIMARY KEY,balance BIGINT NOT NULL)");s.execute("CREATE TABLE shop_notifications(id VARCHAR(36) PRIMARY KEY,seller VARCHAR(36),listing_id VARCHAR(36),buyer VARCHAR(36),price BIGINT,delivered BOOLEAN)");s.execute("CREATE TABLE shop_events(id VARCHAR(36) PRIMARY KEY,listing_id VARCHAR(36),event_type VARCHAR(24),seller VARCHAR(36),seller_name VARCHAR(16),price BIGINT,actor VARCHAR(36),created_at TIMESTAMP)");s.execute("CREATE TABLE shop_journal(id VARCHAR(36) PRIMARY KEY,seller VARCHAR(36),price BIGINT,status VARCHAR(16),recipient VARCHAR(36),seller_name VARCHAR(16),item LONGTEXT,amount INT)");s.execute("INSERT INTO accounts VALUES('seller',10),('buyer',500),('other',500)");s.execute("INSERT INTO shop_journal VALUES('j','seller',125,'PENDING',NULL,'Seller','item',1)");}c.setAutoCommit(false);return c;}
  long value(Connection c,String sql)throws Exception{try(ResultSet r=c.createStatement().executeQuery(sql)){assertTrue(r.next());return r.getLong(1);}}
  @Test void publicationPurchaseAndRepeat()throws Exception{try(Connection c=setup("shop1")){assertTrue(ShopStore.publish(c,"j"));assertFalse(ShopStore.publish(c,"j"));assertNull(ShopStore.buy(c,"j","buyer"));c.commit();assertNotNull(ShopStore.buy(c,"j","other"));assertFalse(ShopStore.cancel(c,"j","seller"));assertEquals(375,value(c,"SELECT balance FROM accounts WHERE uuid='buyer'"));assertEquals(135,value(c,"SELECT balance FROM accounts WHERE uuid='seller'"));assertEquals(2,value(c,"SELECT COUNT(*) FROM shop_events"));assertEquals(1,value(c,"SELECT COUNT(*) FROM shop_notifications WHERE seller='seller' AND buyer='buyer' AND price=125 AND delivered=FALSE"));}}
  @Test void cancellationAndInsufficientFunds()throws Exception{try(Connection c=setup("shop2")){ShopStore.publish(c,"j");assertNotNull(ShopStore.buy(c,"j","seller"));c.createStatement().executeUpdate("UPDATE accounts SET balance=0 WHERE uuid='buyer'");assertNotNull(ShopStore.buy(c,"j","buyer"));assertFalse(ShopStore.cancel(c,"j","other"));assertTrue(ShopStore.cancel(c,"j","seller"));assertFalse(ShopStore.cancel(c,"j","seller"));c.commit();assertEquals(10,value(c,"SELECT balance FROM accounts WHERE uuid='seller'"));}}
  @Test void rollbackRestoresListingAndBalances()throws Exception{try(Connection c=setup("shop3")){ShopStore.publish(c,"j");c.commit();assertNull(ShopStore.buy(c,"j","buyer"));c.rollback();assertEquals(0,value(c,"SELECT COUNT(*) FROM shop_notifications"));assertEquals(500,value(c,"SELECT balance FROM accounts WHERE uuid='buyer'"));assertNull(ShopStore.buy(c,"j","other"));c.commit();}}
  @Test void competingBuyersOnlyOneWins()throws Exception{try(Connection c=setup("shop4")){ShopStore.publish(c,"j");c.commit();ExecutorService pool=Executors.newFixedThreadPool(2);try{Callable<Boolean> buy=()->{try(Connection x=DriverManager.getConnection("jdbc:h2:mem:shop4;MODE=MySQL;LOCK_TIMEOUT=5000")){x.setAutoCommit(false);String result=ShopStore.buy(x,"j",Thread.currentThread().getName().endsWith("1")?"buyer":"other");x.commit();return result==null;}};Future<Boolean> a=pool.submit(buy),b=pool.submit(buy);assertNotEquals(a.get(),b.get());assertEquals(135,value(c,"SELECT balance FROM accounts WHERE uuid='seller'"));}finally{pool.shutdownNow();}}}
}
